tools.example:
model.component("comp1").physics().create("fmf", "FreeMolecularFlow", "geom1");
model.component("comp1").physics("fmf").create("pmp1", "VacuumPump", 2);
model.component("comp1").physics("fmf").feature("pmp1").selection().set(new int[]{12});
model.component("comp1").physics("fmf").create("res1", "Reservoir", 2);
model.component("comp1").physics("fmf").feature("res1").selection().set(new int[]{3});
model.study().create("std1");
model.study("std1").create("stat", "Stationary");
// Application Library: Molecular_Flow_Module/Industrial_Applications/ion_implanter, differential_pumping

model.component("comp1").physics("fmf").create("wall2", "Wall", 2);
model.component("comp1").physics("fmf").feature("wall2").selection().set(new int[]{5, 6});
model.component("comp1").physics("fmf").feature("wall2").set("BCType", "OutgassingWall");
model.component("comp1").physics("fmf").feature("wall2").set("BoundaryCondition", "ThermalDesorptionRate");
model.component("comp1").physics("fmf").feature("wall2").set("Dr", "5e-12[torr*l/(cm^2*s)]");
// Application Library: Molecular_Flow_Module/Benchmarks/outgassing_pipes

model.component("comp1").physics("fmf").feature("wall2").set("BCType", "AdsorptionDesorption");
model.component("comp1").physics("fmf").feature("wall2").set("S", "0.1");
model.study().create("std1");
model.study("std1").create("time", "Transient");
// Application Library: Molecular_Flow_Module/Industrial_Applications/water_adsorption_desorption, uhv_cvd

model.component("comp1").physics("fmf").create("pmp1", "VacuumPump", 2);
model.component("comp1").physics("fmf").feature("pmp1").selection().set(new int[]{20});
model.component("comp1").physics("fmf").feature("pmp1").set("SpecifyPump", "PumpSpeed");
model.component("comp1").physics("fmf").feature("pmp1").set("pspeed", "300[l/s]");
// Application Library: Molecular_Flow_Module/Industrial_Applications/charge_exchange_cell

model.component("comp1").physics("fmf").create("res1", "Reservoir", 2);
model.component("comp1").physics("fmf").feature("res1").selection().set(new int[]{1});
model.component("comp1").physics("fmf").feature("res1").set("p0", "1e-3[Pa]");
// Application Library: Molecular_Flow_Module/Benchmarks/rotating_plate, s_bend_benchmark

model.component("comp1").physics("fmf").create("tv1", "TotalVacuum", 2);
model.component("comp1").physics("fmf").feature("tv1").selection().set(new int[]{9});
// Application Library: Molecular_Flow_Module/Benchmarks/vacuum_capillary (transmission probability)

model.component("comp1").physics("fmf").create("evap1", "Evaporation", 2);
model.component("comp1").physics("fmf").feature("evap1").selection().set(new int[]{4});
// Application Library: Molecular_Flow_Module/Industrial_Applications/evaporator

model.component("comp1").physics("fmf").create("ndr1", "NumberDensityReconDomain", 3);
model.component("comp1").physics("fmf").feature("ndr1").selection().set(new int[]{1});
// Results: Global Evaluation of comp1.fmf.nop_G(0.1,0,0.05)

model.component("comp1").physics().create("tran", "TransitionalFlow", "geom1");
model.component("comp1").physics("tran").create("inl1", "Inlet", 1);
model.component("comp1").physics("tran").create("out1", "Outlet", 1);
model.study().create("std1");
model.study("std1").create("stat", "Stationary");

model.component("comp1").physics("tran").feature("tranp1").set("mu_mat", "userdef");
model.component("comp1").physics("tran").feature("tranp1").set("mu", "1.8e-5[Pa*s]");
// Results: tran.lambda to check the local Knudsen number

model.component("comp1").physics().create("gran", "GranularFlow", "geom1");
model.component("comp1").physics("gran").feature("gp1").set("dg", "2[mm]");
model.component("comp1").physics("gran").create("rel1", "Release", 3);
model.component("comp1").physics("gran").feature("rel1").selection().set(new int[]{2});
model.study().create("std1");
model.study("std1").create("time", "Transient");
// Application Library: Granular_Flow_Module/Flow_and_Material_Characterization/hopper_flow

model.component("comp1").physics("gran").feature("gp1").set("rhog_mat", "userdef");
model.component("comp1").physics("gran").feature("gp1").set("rhog", "2500[kg/m^3]");
model.component("comp1").physics("gran").create("gp2", "GrainPropertiesOther", -1);
model.component("comp1").physics("gran").feature("gp2").set("dg", "3[mm]");
// Application Library: Granular_Flow_Module/Flow_and_Material_Characterization/grain_packing

model.component("comp1").physics("gran").create("wp2", "WallProperties", 2);
model.component("comp1").physics("gran").feature("wp2").selection().set(new int[]{5, 6, 7});
model.component("comp1").physics("gran").feature("wp2").set("WallMotion", "Rotation");
model.component("comp1").physics("gran").feature("wp2").set("omegaw", "2*pi[rad]/2[s]");
// Application Library: Granular_Flow_Module/Mixing_and_Separation/rotating_drum

model.component("comp1").physics("gran").feature("cbg1").set("en", "0.6");
model.component("comp1").physics("gran").feature("cbg1").set("mus", "0.5");
model.component("comp1").physics("gran").feature("cbg1").set("mur", "0.05");
// Application Library: Granular_Flow_Module/Flow_and_Material_Characterization/angle_of_repose

model.component("comp1").physics("gran").create("rel1", "Release", 3);
model.component("comp1").physics("gran").feature("rel1").selection().set(new int[]{2});
model.component("comp1").physics("gran").feature("rel1").set("N", "5000");
model.component("comp1").physics("gran").feature("rel1").set("rt", "range(0,0.01,0.1)");

model.component("comp1").physics("gran").create("inl1", "GrainInlet", 2);
model.component("comp1").physics("gran").feature("inl1").selection().set(new int[]{10});
// Application Library: Granular_Flow_Module/Mixing_and_Separation/ribbon_mixer, Flow_and_Material_Characterization/hopper_flow

model.component("comp1").physics("gran").create("out1", "Outlet", 2);
model.component("comp1").physics("gran").feature("out1").selection().set(new int[]{3});
// Application Library: Granular_Flow_Module/Mixing_and_Separation/vibrating_sieves

model.component("comp1").physics("gran").create("f1", "Force", 3);
model.component("comp1").physics("gran").feature("f1").selection().all();
// GUI: Force F = Stokes drag from an interpolated air velocity field, 3*pi*mu_air*d*(u_air - grain velocity),
// using the grain velocity and diameter variables listed under Insert Expression > Grain statistics

// GUI: Granular Flow > Additional Variables > Compute grain temperature = on
model.component("comp1").physics("gran").create("cht1", "ConvectiveHeatTransfer", 3);
model.component("comp1").physics("gran").feature("cht1").selection().all();

model.component("comp1").physics("gran").feature("wp1").create("facc1", "BoundaryForceAccumulator", 2);
// variable: gran.wp1.facc1.wf (normal contact force on each wall element)
// Application Library: Granular_Flow_Module/Flow_and_Material_Characterization/hopper_flow, Transport/screw_conveyor

model.result().create("pg1", "PlotGroup3D");
model.result("pg1").set("data", "grn1");
model.result("pg1").create("gtrj1", "GrainTrajectories");
// Application Library: every Granular_Flow_Module model uses a Grain dataset and Grain Trajectories plot

model.study().create("std1");
model.study("std1").create("time", "Transient");
model.study("std1").feature("time").set("tlist", "range(0,0.01,2)");
// Application Library: Granular_Flow_Module/Transport/powder_spreading (multi-step study: deposit, then roller)
